// decltype reports the exact type of a name
const int i = 0;
const int& j = i;

// decltype(i) is 'const int'
// decltype(j) is 'const int&'

// decltype on an expression yields the expression's type
struct Point { int x, y; };
Point p;
// decltype(p.x) is 'int'

std::vector<int> v(1);
// decltype(v[0]) is 'int&', because operator[] returns a reference

bool f(const Point& w);
// decltype(f(p)) is 'bool'
